import { registerWebComponents } from '@domg-wc/common';
import { VlRichData, VlSearchResultComponent } from '@domg-wc/components/block';

registerWebComponents([VlRichData, VlSearchResultComponent]);

// Zonder vl-pager in het slot pager toont vl-rich-data het slot content niet, maar het slot no-content: hier dus
// enkel 'Geen resultaten gevonden'. Zie vl-rich-data - pager voor een werkend geheel.

components-block-rich-data--rich-data-pa.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlTitleComponent } from '@domg-wc/components/atom';
import {
    VlPagerComponent,
    VlRichData,
    VlSearchFilterComponent,
    VlSearchResultComponent,
} from '@domg-wc/components/block';
import { VlFormLabelComponent, VlInputFieldComponent, VlSelectComponent } from '@domg-wc/components/form';

registerWebComponents([
    VlRichData,
    VlSearchFilterComponent,
    VlSearchResultComponent,
    VlPagerComponent,
    VlSelectComponent,
    VlTitleComponent,
    VlButtonComponent,
    VlFormLabelComponent,
    VlInputFieldComponent,
]);

// De opties van vl-select zijn een property. De waarde is het pad in de data waarop gesorteerd wordt.
document.querySelector('#rich-data vl-select[slot="sorter"]').options = [
    { label: 'ID', value: 'id' },
    { label: 'Naam manager', value: 'manager.lastName' },
];

// De mock data van de pagina: 25 projecten, Project #1 tot Project #25. Vanaf Project #4 zijn de manager en de
// medewerker telkens Pascal Riquier en Pieter Beckers.
const richDataMockData = {
    data: [
        {
            id: 0,
            name: 'Project #1',
            manager: { firstName: 'Pascal', lastName: 'Riquier' },
            medewerkers: [{ firstName: 'Sander', lastName: 'Kleykens' }],
        },
        {
            id: 1,
            name: 'Project #2',
            manager: { firstName: 'Tom', lastName: 'Coemans' },
            medewerkers: [{ firstName: 'Guy', lastName: 'Wauters' }],
        },
        {
            id: 2,
            name: 'Project #3',
            manager: { firstName: 'Tom', lastName: 'Coemans' },
            medewerkers: [{ firstName: 'Guy', lastName: 'Wauters' }],
        },
        ...Array.from({ length: 22 }, (_, i) => ({
            id: i + 3,
            name: `Project #${i + 4}`,
            manager: { firstName: 'Pascal', lastName: 'Riquier' },
            medewerkers: [{ firstName: 'Pieter', lastName: 'Beckers' }],
        })),
    ],
};

// vl-rich-data filtert, sorteert en pagineert niet zelf: het toont wat je in de slots zet. Het event change volgt bij
// elke invoer in een veld van de filter, bij een reset en bij een andere pagina, met in event.detail formData en
// paging. Vul dan zelf het slot content en zet data.paging: dat zet current-page en total-items op vl-pager en het
// aantal resultaten.
customElements.whenDefined('vl-rich-data').then(() => {
    const richDataComponent = document.querySelector('#rich-data');
    const content = richDataComponent?.querySelector('[slot="content"]');
    const sorter = richDataComponent?.querySelector('[slot="sorter"]');
    const pager = richDataComponent?.querySelector('vl-pager');

    const data = richDataMockData;

    let newData = undefined;

    // In vl-search-result-properties vormt elk label met de data erna een eigenschap.
    const setContentData = (data, from, to) => {
        newData = data;
        content.innerHTML = ``;
        data?.slice(from, to).forEach((project) => {
            const now = new Date().toLocaleString();
            const manager = project.manager;
            const medewerker = project.medewerkers[0];
            const html = `
                <vl-search-result-title>
                    <a href="#">${project.name}</a>
                </vl-search-result-title>
                <vl-search-result-text>
                    <time>Gestart op ${now}</time>
                </vl-search-result-text>
                <vl-search-result-properties>
                    <label>ID</label>
                    <data>${project.id}</data>
                    <label>Naam manager</label>
                    <data>${manager.lastName}</data>
                    <label>Eerste medewerker</label>
                    <data>${medewerker.lastName}</data>
                    <label>
                        <span>Project o.l.v. <strong>manager</strong></span>
                    </label>
                    <data>
                        <span>${project.name} o.l.v. <strong>${manager.firstName} ${manager.lastName}</strong></span>
                    </data>
                </vl-search-result-properties>
            `;
            content.insertAdjacentHTML('beforeend', `<vl-search-result>${html}</vl-search-result>`);
        });
    };

    const filter = (data, pathToKey, value) => {
        if (value === '') {
            return data;
        }
        return data.filter((element) => {
            const valueByPath = findValueByPath(element, pathToKey);
            return valueByPath.includes(value);
        });
    };

    const findValueByPath = (element, pathToKey) => {
        const keys = pathToKey.split('.');

        let current = element;
        for (let i = 0; i < keys.length; i++) {
            if (current[keys[i]] !== undefined) {
                current = current[keys[i]];
            } else {
                return undefined;
            }
        }
        return current.toString();
    };

    richDataComponent?.addEventListener('change', (event) => {
        let newData = data.data;
        let totalItems = data.data.length;

        let filterEntries = undefined;
        if (event.detail.formData) {
            filterEntries = [];
            for (const entry of event.detail.formData.entries()) {
                newData = filter(newData, entry[0], entry[1]);
                totalItems = newData.length;
                filterEntries.push({
                    name: entry[0],
                    value: entry[1],
                });
            }
        }
        const pagination = event.detail.paging;
        if (pagination) {
            const from = (pagination.currentPage - 1) * 10;
            setContentData(newData, from, from + 10);
        }
        if (richDataComponent) {
            richDataComponent.data = {
                paging: {
                    currentPage: event.detail.paging.currentPage,
                    totalItems: totalItems,
                },
                filter: filterEntries,
            };
        }
    });

    // localeCompare vergelijkt als tekst: op ID komt 10 zo voor 2.
    sorter?.addEventListener('vl-change', (event) => {
        const data = newData;
        event.stopPropagation();
        if (!data) return;
        data.sort((firstElement, secondElement) => {
            const keys = event.target?.value?.split('.');

            if (!keys) {
                return 0;
            }

            const getValue = (element) => keys.reduce((value, key) => value[key], element)?.toString() || '';

            const firstValue = getValue(firstElement);
            const secondValue = getValue(secondElement);

            return firstValue.localeCompare(secondValue);
        });
        if (richDataComponent) {
            richDataComponent.data = {
                paging: {
                    currentPage: 1,
                    totalItems: data.length,
                },
            };
        }
        setContentData(data, 0, 10);
    });

    if (richDataComponent) {
        richDataComponent.data = {
            paging: {
                currentPage: 1,
                totalItems: 25,
            },
        };
    }

    // getAttribute geeft een string, '10'; slice zet die zelf om naar een getal.
    setContentData(data.data, 0, pager.getAttribute('items-per-page'));
});
